export default function nextDashboard({values,previousState}) {
 if(!Array.isArray(values))throw Error('Invalid dashboard');
 const index=previousState?.index??0;if(!Number.isInteger(index)||index<0)throw Error('Invalid index');
 if(!values.length)return{state:{index},more:false,url:'https://unused.invalid',site:{},count:index};
 const head=values[0];if(!Array.isArray(head)||['Property','Status','Log Sheet'].some(x=>head.filter(v=>v===x).length!==1))throw Error('Dashboard requires unique Property, Status and Log Sheet headers');
 const p=head.indexOf('Property'),s=head.indexOf('Status'),l=head.indexOf('Log Sheet');const rows=values.slice(1).map((v,i)=>({v,row:i+2})).filter(x=>Array.isArray(x.v)&&x.v.some(y=>y!==''&&y!=null));const seen=new Set();
 for(const {v} of rows){if(typeof v[p]!=='string'||!/^https?:\/\//i.test(v[p])||/[\r\n]/.test(v[p])||seen.has(v[p]))throw Error('Invalid or duplicate Property');seen.add(v[p]);if(!['UP','DOWN'].includes(v[s]))throw Error('Invalid Status');if(typeof v[l]!=='string'||!v[l].trim()||/[\[\]*?:/\\]/.test(v[l]))throw Error('Invalid Log Sheet');}
 if(index>=rows.length)return{state:{index},more:false,url:'https://unused.invalid',site:{},count:index};const x=rows[index];return{state:{index:index+1},more:true,url:x.v[p],site:{property:x.v[p],status:x.v[s],logSheet:x.v[l],row:x.row,statusColumn:s},count:index+1};
}

