export default function assessDashboard({url,index,status,headers,previousState}) {
 const prior=previousState?.index===index?previousState.hops:0;if(!Number.isInteger(prior)||prior<0)throw Error('Invalid redirect state');
 if(Number.isInteger(status)&&status>=300&&status<400&&typeof headers?.location==='string'&&headers.location){if(prior>=21)throw Error('Redirect limit exceeded');let target;try{target=new URL(headers.location,url)}catch{throw Error('Invalid redirect URL')}if(!['http:','https:'].includes(target.protocol)||target.username||target.password)throw Error('Invalid redirect URL');return{state:{index,hops:prior+1,nextUrl:target.toString()},redirect:true,up:false};}
 if(!Number.isInteger(status)||status<100||status>599)throw Error('Invalid HTTP status');return{state:{index,hops:prior,nextUrl:''},redirect:false,up:status<400};
}

