export default function dashboardFields({site,up,now}) {
 if(!site||typeof site.property!=='string'||!['UP','DOWN'].includes(site.status)||typeof site.logSheet!=='string'||!Number.isInteger(site.row)||!Number.isInteger(site.statusColumn)||typeof up!=='boolean')throw Error('Invalid site');
 const time=new Date(now);if(Number.isNaN(time.getTime()))throw Error('Invalid time');const stamp=time.toISOString(),status=up?'UP':'DOWN',event=`${status}_FROM_${site.status}`,quote=x=>"'"+x.replaceAll("'","''")+"'";let col=site.statusColumn+1,label='';while(col){col--;label=String.fromCharCode(65+col%26)+label;col=Math.floor(col/26)}
 const message=`From: n8n uptime\nDate: ${stamp}\n\n${site.property} is ${status}`;return{logRange:quote(site.logSheet)+'!A:G',logValues:[[stamp,stamp.slice(0,7),site.property,event==='UP_FROM_UP',event==='DOWN_FROM_DOWN',event==='UP_FROM_DOWN',event==='DOWN_FROM_UP']],statusRange:`'dashboard'!${label}${site.row}`,statusValues:[[status]],alert:event!=='UP_FROM_UP',subject:`n8n uptime: ${site.property} is ${status}`,message};
}
